def test_streaming_with_context_and_custom_close(self, app, client):
    called = []

    class Wrapper:
        def __init__(self, gen):
            self._gen = gen

        def __iter__(self):
            return self

        def close(self):
            called.append(42)

        def __next__(self):
            return next(self._gen)

        next = __next__

    @app.route("/")
    def index():
        def generate():
            yield "Hello "
            yield flask.request.args["name"]
            yield "!"

        return flask.Response(flask.stream_with_context(Wrapper(generate())))

    rv = client.get("/?name=World")
    assert rv.data == b"Hello World!"
    assert called == [42]

def test_teardown_request_handler_error(app, client):
    called = []
    app.testing = False

    @app.teardown_request
    def teardown_request1(exc):
        assert type(exc) is ZeroDivisionError
        called.append(True)
        # This raises a new error and blows away sys.exc_info(), so we can
        # test that all teardown_requests get passed the same original
        # exception.
        try:
            raise TypeError()
        except Exception:
            pass

    @app.teardown_request
    def teardown_request2(exc):
        assert type(exc) is ZeroDivisionError
        called.append(True)
        # This raises a new error and blows away sys.exc_info(), so we can
        # test that all teardown_requests get passed the same original
        # exception.
        try:
            raise TypeError()
        except Exception:
            pass

    @app.route("/")
    def fails():
        raise ZeroDivisionError

    rv = client.get("/")
    assert rv.status_code == 500
    assert b"Internal Server Error" in rv.data
    assert len(called) == 2

